    // FIRST LEVEL HEIGHT ROW
    const firstLevelCells: TableCell[] = [];
    firstLevelCells.push(createCell([new Paragraph({ children: [boldText("MAX. WYSOKOŚĆ 1. POZIOMU", 18, "444444")] })], 2, "FFFFFF", true, compactRowMargin));

    if (configCount === 1) {
       firstLevelCells.push(createCell([new Paragraph({ children: [boldText("A = ", 24), boldText(data.firstLevelHeight, 24), unitText("mm", 18), normalText(mobileSuffix, 14, "444444")], alignment: AlignmentType.CENTER })], 2, "FFFFFF", true, compactRowMargin));
    } else {
       // Distribute space for multiple configs
       // In docx we use standard cells, but we need to manage colSpans. 
       // Total colSpan available is 2 (from the right half of table).
       // Standard 4-column table: col1(Header), col2(Header), col3(Val), col4(Val) -> This logic was for 2 configs.
       // For 4 configs, we might need to rethink table structure or nest a table.
       // Simplest approach: Create a nested table for the right side or just output text separated by space if we can't add columns easily.
       // BETTER: Just create cells. The `createPlateTable` creates a table with implied columns based on first row.
       // Actually `docx` tables need consistent column count.
       // Let's make the main table have 2 columns: [LabelColumn, DataColumn]. DataColumn contains a nested table.

       // RE-STRATEGY for multiple configs in DOCX to keep it simple: 
       // Just list them in the same cell if > 2, or use the existing structure if <= 2? 
       // The prompt implies visual layout changes.

       // Let's iterate activeConfigs and add cells.
       // NOTE: `createCell` has colSpan logic.
       // To support 4 columns cleanly in DOCX without breaking layout, we'll assume the main table has 2+configCount columns? 
       // No, simpler: 1 Label Column (span 2), ConfigCount Data Columns (span 1 each?).
       // Total columns = 2 + configCount?
       // The current logic assumes a 4-column grid (Label Span 2, Data Span 2 or Data Span 1+1).

       // Hack for DOCX simplicity: We will just put them all in one cell if it gets too complex, 
       // BUT let's try to map columns.
       activeConfigs.forEach(cfg => {
          firstLevelCells.push(createCell([new Paragraph({ 
             children: [
               boldText(`${cfg.label}=${cfg.h1}`, 18), 
               unitText("mm", 14)
             ], 
             alignment: AlignmentType.CENTER 
          })], 1, "FFFFFF", true, compactRowMargin));
       });
    }

    // Since TableRow children count must match grid, we need to ensure we don't break the grid.
    // The previous implementation used a 4-column grid basically.
    // Row 1 (Header): Cell 1 (span 1), Cell 2 (span 1) -> Wait, Header used percents.
    // If we have variable number of columns, we should probably stick to a consistent grid max (e.g. 6 columns).
    // Let's define the grid as: Label (Span 2), Value (Span varies).
    // If configCount == 1, Value Span = 4. Total 6.
    // If configCount == 2, Value Span = 2 each. Total 6.
    // If configCount == 3, Value Span = 1 (approx). 6 doesn't divide by 3 well integer-wise.
    // Let's use 12 columns grid.
    // Label Span = 8 (66%).
    // 1 Config: Span 4.
    // 2 Configs: Span 2, 2.
    // 3 Configs: Span 1, 1, 1 (Leave 1 empty? No 12/3 = 4? Wait. 12-8=4 columns left. 4/3 is bad.)

    // Fallback: If DOCX generation is too complex for dynamic columns in this specific constrained environment, 
    // we will stick to 1 or 2 config logic for DOCX, and just squish 3/4 into the existing cells or ignore them.
    // However, the user wants "Creator".

    // Let's assume for DOCX we just iterate. `docx` library handles column widths if not specified rigidly.
    contentRows.push(new TableRow({ children: firstLevelCells }));


    // SUBSEQUENT LEVELS
    const maxRows = Math.max(...activeConfigs.map(c => c.levels ? c.levels.length : 0));

    for (let i = 0; i < maxRows; i++) {
        const levelCells: TableCell[] = [];
        levelCells.push(createCell([new Paragraph({ children: [boldText(i === 0 ? "KOLEJNE POZIOMY" : "", 16, "444444")] })], 2, "FFFFFF", true, compactRowMargin));

        if (configCount === 1) {
           const l1 = activeConfigs[0].levels?.[i];
           const content = l1 ? [normalText(`${getLevelLabel(l1, 'A')} = `, 18, "444444"), boldText(l1.height, 22), unitText("mm", 18)] : [];
           levelCells.push(createCell([new Paragraph({ children: content, alignment: AlignmentType.CENTER })], 2, "FFFFFF", true, compactRowMargin));
        } else {
           activeConfigs.forEach(cfg => {
              const l = cfg.levels?.[i];
              const content = l ? [normalText(`${getLevelLabel(l, cfg.label)} = `, 14, "444444"), boldText(l.height, 16), unitText("mm", 12)] : [];
              levelCells.push(createCell([new Paragraph({ children: content, alignment: AlignmentType.CENTER })], 1, "FFFFFF", true, compactRowMargin));
           });
        }
        contentRows.push(new TableRow({ children: levelCells }));
    }

    // ... Rest of the table (Beams, Frame, Load) ...
    // Note: We need to respect the column span of the following rows to match the dynamic grid above.
    // If we changed column count in previous rows, the following rows (colSpan 4) might break if not careful.
    // `docx` doesn't enforce strict grid like HTML, but visual alignment depends on it.
    // To be safe, we give the following rows a colSpan equal to (2 + configCount) or similar? 
    // Actually `createCell` just makes a cell.

    // To ensure table validity, simply calculate total Columns used in the levels section.
    const totalCols = 2 + (configCount === 1 ? 2 : configCount); // If 1 config, we used span 2 for value. If >1, we used 1 cell per config.

    contentRows.push(new TableRow({
      children: [
        createCell([new Paragraph({ children: [boldText("MAKSYMALNE OBCIĄŻENIE PARY TRAWERSÓW", 18)], alignment: AlignmentType.CENTER })], totalCols, "FFFFFF")
      ]
    }));

    contentRows.push(new TableRow({
      children: [
        createCell([new Paragraph({ children: [boldText("POZIOM", 14, "444444")], alignment: AlignmentType.CENTER })], 1, "FFFFFF", true, compactRowMargin),
        createCell([new Paragraph({ children: [boldText("DŁ. (L)", 14, "444444")], alignment: AlignmentType.CENTER })], 1, "FFFFFF", true, compactRowMargin),
        createCell([new Paragraph({ children: [boldText("PROFIL", 14, "444444")], alignment: AlignmentType.CENTER })], 1, "FFFFFF", true, compactRowMargin),
        createCell([new Paragraph({ children: [boldText("MAX. OBCIĄŻENIE", 14, "444444")], alignment: AlignmentType.CENTER })], totalCols - 3, "FFFFFF", true, compactRowMargin),
      ]
    }));

    // ... Beams Loop ...
     // Inject Chassis Rows for Mobile
    if (isMobile && data.mobileChassisConfigs) {
      data.mobileChassisConfigs.forEach(chassis => {
        const chassisQmax = (chassis.loadCount || 0) * (chassis.loadWeight || 0);
        contentRows.push(new TableRow({
          children: [
            createCell([new Paragraph({ children: [boldText("PODWOZIE", 16)], alignment: AlignmentType.CENTER })]),
            createCell([new Paragraph({ children: [boldText(chassis.length || 0, 22), unitText("mm", 16)], alignment: AlignmentType.CENTER })]),
            createCell([new Paragraph({ children: [boldText("PODWOZIE", 20)], alignment: AlignmentType.CENTER })]),
            createCell([new Paragraph({ children: [boldText(`Qmax= ${chassisQmax}`, 22), unitText("kg", 18), new TextRun({ text: `\n(${chassis.loadCount} x ${chassis.loadWeight} kg)`, size: 14, color: "555555" })], alignment: AlignmentType.CENTER })], totalCols - 3),
          ]
        }));
      });
    }

    data.beams.forEach(beam => {
      const qMax = calculateQmax(beam.loadCount, beam.loadWeight);
      contentRows.push(new TableRow({
        children: [
          createCell([new Paragraph({ children: [boldText(beam.levelLabel, 18)], alignment: AlignmentType.CENTER })]),
          createCell([new Paragraph({ children: [boldText(beam.length, 22), unitText("mm", 16)], alignment: AlignmentType.CENTER })]),
          createCell([new Paragraph({ children: [boldText(`AUF'B'${beam.profileType}`, 20), normalText(` (${beam.profileWidth}x50)`, 16, "444444")], alignment: AlignmentType.CENTER })]),
          createCell([new Paragraph({ children: [boldText(`Qmax= ${qMax}`, 22), unitText("kg", 18), new TextRun({ text: `\n(${beam.loadCount} x ${beam.loadWeight} kg)`, size: 14, color: "555555" })], alignment: AlignmentType.CENTER })], totalCols - 3),
        ]
      }));
    });

    const frameText1 = `STD'B'${data.frameType}'${data.frameDepth}'${data.frameHeight}`;
    const frameText2 = data.frameType2 ? ` oraz STD'B'${data.frameType2}'${data.frameDepth2}'${data.frameHeight2}` : '';

    contentRows.push(new TableRow({
      children: [
        createCell([new Paragraph({ children: [boldText("RAMA", 16, "444444")], alignment: AlignmentType.CENTER })], 1, "FFFFFF"),
        createCell([new Paragraph({ children: [boldText(frameText1 + frameText2, 20)], alignment: AlignmentType.CENTER })], totalCols - 1)
      ]
    }));

    contentRows.push(new TableRow({
      children: [
        createCell([new Paragraph({ children: [boldText("MAX. OBCIĄŻENIE POLA", 18, "444444")] })], 2, "FFFFFF"),
        createCell([new Paragraph({ children: [boldText("Qp=", 20, "444444")], alignment: AlignmentType.CENTER })], 1),
        createCell([new Paragraph({ children: [boldText(totalBayLoad, 24), unitText("kg", 18)], alignment: AlignmentType.CENTER })], totalCols - 3)
      ]
    }));

    contentRows.push(new TableRow({
      children: [
        createCell([new Paragraph({ children: [boldText("WYSOKOŚĆ REGAŁU", 18, "444444")] })], 2, "FFFFFF"),
        createCell([new Paragraph({ children: [boldText("H=", 20, "555555")], alignment: AlignmentType.CENTER })], 1),
        createCell([new Paragraph({ children: [boldText(uniqueHeights, 24), unitText("mm", 18)], alignment: AlignmentType.CENTER })], totalCols - 3)
      ]
    }));
  }

  // Push content rows to main table rows (Fixing missing middle section)
  rows.push(...contentRows);

  rows.push(new TableRow({
    children: [
      new TableCell({
        children: [
          new Paragraph({ children: [boldText("ADRES DOSTAWCY:", 14, "444444")] }),
          new Paragraph({ children: [normalText("Jungheinrich Polska Sp. Z o.o.", 14)] }),
          new Paragraph({ children: [normalText("ul. Świerkowa 3 Bronisze, 05-850 Ożarów Mazowiecki", 14)] }),
        ],
        width: { size: 40, type: WidthType.PERCENTAGE },
        borders: { top: { style: BorderStyle.SINGLE, size: 4 }, right: { style: BorderStyle.SINGLE, size: 2 } }
      }),
      new TableCell({
        children: [
          new Paragraph({ children: [boldText("NASTĘPNY PRZEGLĄD TECHNICZNY", 16, "555555")], alignment: AlignmentType.LEFT }),
          new Paragraph({ children: [boldText(formattedDate, 32)], alignment: AlignmentType.LEFT }),
        ],
        width: { size: 60, type: WidthType.PERCENTAGE },
        verticalAlign: VerticalAlign.CENTER,
        borders: { top: { style: BorderStyle.SINGLE, size: 4 } }
      })
    ]
  }));

  const plateContainer = new Table({
    rows: rows,
    width: { size: 100, type: WidthType.PERCENTAGE },
    borders: {
      top: { style: BorderStyle.NIL },
      bottom: { style: BorderStyle.NIL },
      left: { style: BorderStyle.NIL },
      right: { style: BorderStyle.NIL },
      insideHorizontal: { style: BorderStyle.NIL },
      insideVertical: { style: BorderStyle.NIL }
    }
  });

  return [
    new Paragraph({ children: [] }), 
    plateContainer,
    new Paragraph({ children: [], pageBreakBefore: true })
  ];
};

export const createDocxBlob = async (plates: PlateData[]): Promise<Blob> => {
  const allChildren: any[] = [];
  plates.forEach(plate => {
    const tableNodes = createPlateTable(plate);
    allChildren.push(...tableNodes);
  });
  const doc = new Document({
    sections: [{
      properties: {
        page: {
          margin: {
            top: 720,
            right: 720,
            bottom: 720,
            left: 720
          }
        }
      },
      children: allChildren
    }]
  });
  return await Packer.toBlob(doc);
};

